<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class PassengerAuditLog {
 public static function install(): void { global $wpdb; $t=$wpdb->prefix.'avanik_passenger_audit'; $c=$wpdb->get_charset_collate(); require_once ABSPATH.'wp-admin/includes/upgrade.php'; dbDelta("CREATE TABLE {$t} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL DEFAULT 0, booking_id varchar(80) NOT NULL, passenger_id bigint unsigned NOT NULL DEFAULT 0, action varchar(40) NOT NULL, fields text NULL, ip_address varchar(64) DEFAULT '', created_at datetime NOT NULL, PRIMARY KEY(id), KEY booking_id(booking_id), KEY passenger_id(passenger_id), KEY user_id(user_id), KEY action(action)) {$c};"); }
 public static function record(string $action,string $booking_id,int $passenger_id=0,array $fields=[]): void { global $wpdb; $wpdb->insert($wpdb->prefix.'avanik_passenger_audit',['user_id'=>get_current_user_id(),'booking_id'=>sanitize_text_field($booking_id),'passenger_id'=>absint($passenger_id),'action'=>sanitize_key($action),'fields'=>wp_json_encode(array_values(array_unique(array_map('sanitize_key',$fields)))),'ip_address'=>self::ip(),'created_at'=>current_time('mysql')]); }
 public static function recent_for_booking(string $booking_id,int $limit=100): array { global $wpdb; $limit=max(1,min(500,$limit)); return $wpdb->get_results($wpdb->prepare('SELECT * FROM '.$wpdb->prefix.'avanik_passenger_audit WHERE booking_id=%s ORDER BY id DESC LIMIT %d',$booking_id,$limit),ARRAY_A)?:[]; }
 private static function ip(): string { $ip=$_SERVER['REMOTE_ADDR']??''; return filter_var($ip,FILTER_VALIDATE_IP)?$ip:''; }
}